INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('chungmuro_council_audit', 'story', 'vol1_ch4', 'chungmuro', '十王清算会', '会议之后的第七天，十王又聚在了一起——这一次，铁王坐在了圆桌旁。\n\n他们管这叫「清算」：每位王报出手下的人数、物资、碎片，谁的账对不上，谁的位置就要往后挪。纸王念账，影王不说话，铁王一直在看你。\n\n念到最后一页时，纸王停了一下。"还有一笔，"他说，"记在所有人名下，却不属于任何一位王。"他抬头，看向你。', 12, 8, 0, '{"choice_unlockers":[{"event_key":"chungmuro_conspiracy_story","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[0]}],"personal_contexts":[{"story_flag":"story_council_spoke","text":"上一次会议上，你当着九位王说出了「作者」。今天，他们都记得你。"},{"story_flag":"story_council_silent","text":"上一次你什么也没说。纸王那一页被折了角——他还在等你开口。"}]}', '{}', '{"storyPityReset":true}', '[{"label":"「那一笔，记在我名下。」","consequence_text":"圆桌边安静得能听见稿纸翻动。铁王第一个笑出声，笑声里没有一点高兴。\\"一个没有王座的人，替十王记账？\\"影王终于开口：\\"他不是来要王座的。他是来告诉你们，账本会改写。\\"那天散会时，每位王都多看了你一眼。","rewards_override":{"storyFragments":8,"exp":180,"channelHeat":45},"title_bias":{"title_truth_bringer":2},"unlock_events":["chungmuro_shadow_vote"]},{"label":"「我只是影王带来的人。」","consequence_text":"纸王点点头，把那一页压到了最底下。可你注意到，他用指甲在页边折了一个很小的角——那是留着以后再翻的记号。铁王收回目光，像是确认了什么。影王一直没回头，只在散会时低声说：\\"他们会再来找你的。\\"","rewards_override":{"storyFragments":6,"exp":160,"coins":80},"title_bias":{"title_calculating":2},"unlock_events":["chungmuro_shadow_vote"]}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('chungmuro_shadow_vote', 'story', 'vol1_ch4', 'chungmuro', '影王的一票', '影王把你叫到一条没有灯的通道里。他说十王要投票：铁王的位置，留还是不留。九位王各有一票，影王的那一票，他想交给你。\n\n"我投什么都一样，"他说，"他们知道我想什么。可你投——他们不知道你看过多远。"\n\n通道另一头，刘众赫靠在墙上，没有走近。他看着你，什么也没说。你知道他在等：这一次，他不替你决定。', 12, 8, 0, '{"choice_unlockers":[{"event_key":"chungmuro_council_audit","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[0]}]}', '{}', '{"storyPityReset":true}', '[{"label":"「留下他。忠武路需要一个看得见的王。」","consequence_text":"影王沉默了一会儿：\\"你见过没有王的地方会变成什么样。\\"他没说同意，也没说反对，只是把那枚代表一票的铁片放进你手心。刘众赫转身走了，走前留下一句：\\"你选了秩序。那就别让它变成下一个笼子。\\"","rewards_override":{"storyFragments":8,"exp":200,"coins":100},"title_bias":{"title_pragmatic":2},"unlock_events":["chungmuro_power_fork"]},{"label":"「换掉他。清算会上，他报的数里没有人。」","consequence_text":"影王第一次露出近似笑的表情：\\"你听出来了。他报的是罐头和碎片，从来不报人。\\"他把铁片放进你手心，压得很重。通道尽头，刘众赫终于走过来，跟你并肩站着：\\"换掉一个王很容易。难的是之后谁坐上去。\\"他看着你，\\"想好了再投。\\"","rewards_override":{"storyFragments":10,"exp":200,"channelHeat":50},"title_bias":{"title_defiant":2},"unlock_events":["chungmuro_power_fork"]}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('chungmuro_power_fork', 'story', 'vol1_ch4', 'chungmuro', '圆桌的主位', '投票那天，铁片落进铁盒的声音一声接一声。最后一枚是你的。\n\n纸王数完票，宣布了铁王的去留——那正是你投下的结果。可他没有散会，而是指了指圆桌最上首那把一直空着的椅子："十王从来没有主位。谁坐上去，谁就要替十王做以后的每一次清算。"他看着你，"今天的结果是你定的。这把椅子，也该你来定。"\n\n九位王都在看你。刘众赫站在门口，影王站在阴影里。你忽然明白，从这一刻起，不论你说什么，忠武路都会记住：是你替它做的决定。', 12, 8, 0, '{"choice_unlockers":[{"event_key":"chungmuro_shadow_vote","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[0]}]}', '{}', '{"storyPityReset":true}', '[{"label":"「我来坐。在找到更好的人之前。」","consequence_text":"你走过去，坐上那把冰冷的椅子。没有人鼓掌，也没有人反对。纸王在账本上写下新的一行，笔迹第一次没有自己改写。刘众赫看了你很久，最后只说：\\"那就坐稳。\\"——你成了十王圆桌上第一个主位，也是唯一一个读过结局的人。","rewards_override":{"storyFragments":15,"exp":300,"coins":150},"title_bias":{"title_liberator":3},"set_story_flags":{"story_a0_took_seat":true},"route_pending":true},{"label":"「谁也不坐。这把椅子，拆了。」","consequence_text":"你走过去，当着九位王的面，把那把椅子推倒在站台上。铁的声音在隧道里回响了很久。有人骂，有人笑，影王什么也没说，只是把身后的阴影收了起来。刘众赫走到你身边：\\"你知道你刚刚让多少人不知道该听谁的了吗？\\"他顿了顿，\\"……很好。那就让他们学会听自己的。\\"","rewards_override":{"storyFragments":12,"exp":300,"channelHeat":60},"title_bias":{"title_revolutionary":3},"set_story_flags":{"story_a0_broke_seat":true},"route_pending":true}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('dongmyo_ledger_delivery', 'story', 'vol1_ch4', 'dongmyo', '送账本', '不管你撕下了那一页，还是把账本原样放了回去，朴素英都找到了你。她说抵抗组织在东庙有一个旧情报站，要你把铁王的账带过去——带不了纸，就带在脑子里。\n\n东庙市场比你第一次来时更挤了。卖记忆的摊位多了三家，每家的价钱都比上周高。你在人群里走了很久，才找到那家门口挂着空鸟笼的店。\n\n店主是个老人，听你说出暗号，只问了一句："账上，有多少个名字？"', 12, 8, 0, '{"choice_unlockers":[{"event_key":"chungmuro_compromise_ledger","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[0]}],"personal_contexts":[{"story_flag":"story_ledger_taken","text":"撕下来的那一页一直贴身放着，边角已经被汗浸软了。"},{"story_flag":"story_ledger_hidden","text":"账本你放回去了，可上面的每个名字你都记得。"}]}', '{}', '{"storyPityReset":true}', '[{"label":"把记得的名字一个一个说出来","consequence_text":"你说了很久。老人一边听一边在旧收据背面写，写满一张换一张。说到你自己的名字时，他停下笔，抬头看了你一眼：\\"你把自己也算进去了。\\"他把收据叠好收进鸟笼的夹层里，\\"好。账本不在铁王手里了——在你这里。\\"","rewards_override":{"storyFragments":8,"exp":180,"channelHeat":40},"title_bias":{"title_rememberer":2},"unlock_events":["dongmyo_resistance_weigh"]},{"label":"「名字我不能说。我只告诉你，账本在哪。」","consequence_text":"老人看了你很久，然后点点头：\\"你比朴素英说的还谨慎。\\"他递给你一枚旧铜钱，\\"以后来东庙，把这个放在任何一个摊位上，他们都会让你看后台。\\"你忽然明白，你不是来送账本的——你是来被确认的。","rewards_override":{"storyFragments":7,"exp":160,"coins":90},"title_bias":{"title_information_broker":2},"unlock_events":["dongmyo_resistance_weigh"]}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('dongmyo_resistance_weigh', 'story', 'vol1_ch4', 'dongmyo', '市场里的眼线', '第二天，你在东庙看见了一个熟面孔——铁王仓库里清点物资的那个人。他假装在挑旧手表，眼睛却一直跟着你。\n\n朴素英的人在你身后两个摊位外，等你的信号。只要你点头，那个人今天就不会再回忠武路。\n\n刘众赫曾经告诉过你：有些人值得救，有些人值得用。他从来没告诉过你，怎么分辨。', 12, 8, 0, '{"choice_unlockers":[{"event_key":"dongmyo_ledger_delivery","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[0]}]}', '{}', '{"storyPityReset":true}', '[{"label":"不点头，走过去和他说话","consequence_text":"你在他旁边蹲下，拿起一块停了的表。\\"它停在哪一刻？\\"你问。他愣住了。你们聊了一刻钟，聊表、聊忠武路的伙食、聊他在家乡的妹妹。走前他低声说：\\"铁王让我盯你。我就说……没看见你。\\"朴素英在远处皱眉，却没有阻止。","rewards_override":{"storyFragments":7,"exp":180,"channelHeat":45},"title_bias":{"title_compassionate":2},"unlock_events":["geumho_resistance_muster"]},{"label":"点头，让抵抗组织带走他","consequence_text":"你把手里的表放下，轻轻点了点头。人群一晃，那个人就不见了。没有声音，没有挣扎。晚上朴素英告诉你，他被送去了金湖站，\\"不会伤他，只是让铁王少一双眼睛。\\"她看着你，\\"你下决定的速度，比我想的快。\\"","rewards_override":{"storyFragments":9,"exp":180,"coins":100},"title_bias":{"title_calculating":2},"unlock_events":["geumho_resistance_muster"]}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('geumho_resistance_muster', 'story', 'vol1_ch4', 'geumho_station', '金湖站的集结', '抵抗组织的人从各个站陆续来到金湖站。他们在废弃的检票口后面搭起帆布，点着几盏省电的灯。\n\n朴素英站在一只木箱上，没有喊口号，只是说："铁王的账，现在有人记得了。"她指向你。几十双眼睛同时看过来——他们看的不是刘众赫带来的人，是握着账本的人。\n\n有人问："那我们接下来做什么？"朴素英没有回答。她在等你。', 12, 8, 0, '{"choice_unlockers":[{"event_key":"dongmyo_resistance_weigh","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[0]}]}', '{}', '{"storyPityReset":true}', '[{"label":"「先把账上每个名字找回来。」","consequence_text":"你说完，人群里有人低声重复了一遍，然后是第二个、第三个。帆布下面第一次有了一点声音，不大，但很整齐。朴素英从木箱上跳下来，把一张写满站名的纸塞给你：\\"那就从这里开始。\\"你知道，从今晚起，这些人会跟着一本账走——而那本账，在你脑子里。","rewards_override":{"storyFragments":12,"exp":260,"channelHeat":55},"title_bias":{"title_liberator":2},"set_story_flags":{"story_a1_muster_names":true},"route_pending":true},{"label":"「先等。等铁王自己露出破绽。」","consequence_text":"有人不满地出声，但朴素英抬手压了下去。\\"他是对的，\\"她说，\\"我们没有第二次机会。\\"散会后，她把你拉到一边：\\"等，比冲更难。你最好知道你在等什么。\\"你知道——你在等那本书里，还没写到的那一页。","rewards_override":{"storyFragments":10,"exp":240,"coins":120},"title_bias":{"title_contemplative":2},"set_story_flags":{"story_a1_muster_wait":true},"route_pending":true}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('chungmuro_paper_summon', 'story', 'vol1_ch4', 'chungmuro', '纸王的书房', '你以为纸王会等你很久。可第三天夜里，录事又来找你了，这次他手里拿的不是名册，是一张折得很小的稿纸。\n\n稿纸上只有一句话，是纸王的字："它动了。"\n\n书房里，四面墙的稿纸比上次翻得更快。纸王坐在中间，面前摊着你那一页——那一大片空白的最上方，多了一行很淡的字。', 12, 8, 0, '{"choice_unlockers":[{"event_key":"chungmuro_script_blank","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[1]}],"personal_contexts":[{"story_flag":"story_script_self_written","text":"你说过要自己来写。那一页，好像真的听见了。"},{"story_flag":"story_script_kept_blank","text":"你让那一页先空着。纸王说他替你守着——可它自己动了。"}]}', '{}', '{"storyPityReset":true}', '[{"label":"凑近去看那一行字","consequence_text":"字迹太淡，你只认出了几个词：「车站」「名字」「他没有说」。纸王声音发紧：\\"这是你做过的事。它在倒着写。\\"你想起车站里那个黑衣男人——你没有告诉他你是谁。原来这一页，从那里就开始记了。","rewards_override":{"storyFragments":8,"exp":180,"channelHeat":40},"title_bias":{"title_truth_seeker":2},"unlock_events":["chungmuro_blank_revision"]},{"label":"「先别看。告诉我，它为什么动了。」","consequence_text":"纸王把手按在那一页上，像是怕它跑掉。\\"因为你承认了。\\"他说，\\"在录事面前，你说了『我读过』。一个读者承认自己是读者——这一页就有了第一个字。\\"他看着你，\\"你说出口的每一句话，它都在听。\\"","rewards_override":{"storyFragments":7,"exp":170,"coins":80},"title_bias":{"title_contemplative":2},"unlock_events":["chungmuro_blank_revision"]}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('chungmuro_blank_revision', 'story', 'vol1_ch4', 'chungmuro', '空白页上的未来', '你在纸王的书房里待到了天亮。那一行字越写越长，后面又跟上了第二行、第三行——写的不是你做过的事，是你还没做的。\n\n「他会在忠武路留下名字。」「或者，他会让所有人忘记他来过。」两行字并排写着，墨色一样深。\n\n纸王的手在抖。"我写了一辈子别人的结局，"他说，"从没见过一页纸，同时写两个。"', 12, 8, 0, '{"choice_unlockers":[{"event_key":"chungmuro_paper_summon","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[1]}]}', '{}', '{"storyPityReset":true}', '[{"label":"「两个都可能。那就是我还没选。」","consequence_text":"纸王怔了一下，然后慢慢笑起来：\\"对。没选。\\"他把一支笔推到你面前——不是他的那支，是一支从没用过的新笔。\\"等你选了，用这支写。我的笔，写不了你。\\"","rewards_override":{"storyFragments":9,"exp":200,"channelHeat":45},"title_bias":{"title_script_rewriter":2},"unlock_events":["chungmuro_name_fork"]},{"label":"「谁在写？不是你，也不是我。」","consequence_text":"纸王沉默了很久。\\"我不知道。\\"这是他第一次承认不知道。书房里的稿纸停止了翻动，一张接一张静下来，像在屏住呼吸。最后他说：\\"也许这就是你来这里的原因——去问那个写的人。\\"他把那一页折起来，放进你手里。","rewards_override":{"storyFragments":8,"exp":200,"coins":100},"title_bias":{"title_seeker":2},"unlock_events":["chungmuro_name_fork"]}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('chungmuro_name_fork', 'story', 'vol1_ch4', 'chungmuro', '写，还是抹去', '你一个人回到了第一次被认出的那张折叠桌前。录事不在，名册摊开着，你的那一行还在，旁边那一行小字也还在——「读过那本书的人」。\n\n你从口袋里拿出纸王的那一页，又拿出那支新笔。\n\n你可以在名册上写下真名，让忠武路、让十王、让所有翻到这一页的人都知道：这个世界里，有一个读者。你也可以把那一行小字划掉——从今往后，名册不再认识你。', 12, 8, 0, '{"choice_unlockers":[{"event_key":"chungmuro_blank_revision","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[1]}]}', '{}', '{"storyPityReset":true}', '[{"label":"在名册上写下真名","consequence_text":"笔尖落下，纸王那一页同时亮了一下——空白的地方，出现了和名册上一模一样的名字。第二天，站台上开始有人用那个名字叫你。有人好奇，有人害怕，也有人远远地朝你点头。你不再是人群里的影子了。从今天起，被看见，就是你的路。","rewards_override":{"storyFragments":15,"exp":300,"channelHeat":60},"title_bias":{"title_first_reader":3},"set_story_flags":{"story_u0_wrote_name":true},"route_pending":true},{"label":"划掉「读过那本书的人」","consequence_text":"你划得很用力。最后一笔落下时，纸王那一页上的两行字一起淡了下去，只剩下最上面那句「他没有说」。第二天，录事看见你，愣了愣，像是在想这张脸在哪见过——然后低下头，继续写别人的名字。你又变回了一个没人认识的人。只是这一次，是你自己选的。","rewards_override":{"storyFragments":12,"exp":300,"coins":150},"title_bias":{"title_free_spring":3},"set_story_flags":{"story_u0_erased_mark":true},"route_pending":true}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('geumho_wall_message', 'story', 'vol1_ch4', 'geumho_station', '墙上的回信', '你离开读者之墙已经很多天了。直到有一天，你在金湖站的换乘通道里，看见了一个只有读过那面墙的人才认得出的记号。\n\n记号下面有一行粉笔字，像是专门写给你的："看到你了。往下走。"\n\n通道尽头是一段早就停用的月台，铁栅栏上挂着一把没锁的锁。', 12, 8, 0, '{"choice_unlockers":[{"event_key":"chungmuro_hidden_reader_wall","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[1]}],"personal_contexts":[{"story_flag":"story_nameless_signed_wall","text":"你在墙上写下了名字。有人来找你，只是早晚的事。"},{"story_flag":"story_nameless_read_wall","text":"你什么也没写，只留下一个记号。现在，有人回应了它。"}]}', '{}', '{"storyPityReset":true}', '[{"label":"推开栅栏，下去","consequence_text":"月台上很暗，只有一盏手电在远处晃了一下，又灭了。你没有喊，只是在最近的柱子上，画了同样的记号。过了很久，柱子另一面传来很轻的敲击声——三下，停一停，再两下。你笑了。有人在等你，而且和你一样小心。","rewards_override":{"storyFragments":8,"exp":180,"channelHeat":35},"title_bias":{"title_pathfinder":2},"unlock_events":["geumho_nameless_cell"]},{"label":"在记号旁边回一行字，然后离开","consequence_text":"你写：\\"还没准备好。但我知道你们在。\\"第二天你再经过，那行字下面多了一句回答：\\"我们也是这么开始的。\\"粉笔字旁边，压着一小包碎片——不多，刚好够你撑过这个星期。","rewards_override":{"storyFragments":7,"exp":160,"coins":80},"title_bias":{"title_humble_reader":2},"unlock_events":["geumho_nameless_cell"]}]', NULL);
