(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
VALUES
('geumho_nameless_cell', 'story', 'vol1_ch4', 'geumho_station', '没有名字的人们', '他们一共五个人，都住在停用月台的检修间里。没有人报名字，彼此只用记号称呼：「圆圈」「三道杠」「折角」……\n\n年纪最大的「圆圈」给你倒了一杯热水："我们都读过那本书，读到的地方不一样。有人读到第三章就停了，有人读过了大半。"她看着你，"你读到哪里？"\n\n你忽然意识到：这是你醒来之后，第一次有人问你这个问题，而不是怀疑你。', 12, 8, 0, '{"choice_unlockers":[{"event_key":"geumho_wall_message","choice_indices":[0,1]}],"required_choices":[{"event_key":"station_first_trace","choice_indices":[1]}]}', '{}', '{"storyPityReset":true}', '[{"label":"如实说出你读到的地方","consequence_text":"你说完，检修间里安静了很久。「三道杠」低声骂了一句，不是骂你，是骂那本书。「圆圈」把杯子往你手边推了推：\\"你读得最远。\\"她没说这是好事还是坏事，只说，\\"那以后，我们都听你的记号。\\"","rewards_override":{"storyFragments":9,"exp":200,"channelHeat":45},"title_bias":{"title_story_bearer":2},"unlock_events":["chungmuro_reader_anchor"]},{"label":"「读到哪里不重要。重要的是现在在哪。」","consequence_text":"「折角」笑出了声：\\"这句话我要写到墙上。\\"「圆圈」点点头：\\"那就说现在。\\"你们聊到深夜：哪个站的水还能喝，哪个王的人最近在找「读者」，哪里还有像你们一样藏起来的人。离开时，你有了一张只有记号的地图。","rewards_override":{"storyFragments":8,"exp":200,"coins":100},"title_bias":{"title_world_walker":2},"unlock_events":["chungmuro_reader_anchor"]}]', NULL);
INSERT IGNORE INTO `exploration_events`
(`event_key`, `event_type`, `stage_key`, `location_key`, `name`, `description`, `weight`, `stamina_cost`, `repeatable`, `required_conditions_json`, `rewards_json`, `progress_effects_json`, `choices_json`, `log_template`)
